import{c as e,Q as a,j as r,m as o}from"./chunks/framework.BXc4yaFE.js";const u=JSON.parse('{"title":"Sub-Agent 與 Agent Team（多代理協作）— 深度研究報告","description":"","frontmatter":{},"headers":[],"relativePath":"research/reports/archive/2026-06-03-subagent-agent-team-deep-research.md","filePath":"research/reports/archive/2026-06-03-subagent-agent-team-deep-research.md","lastUpdated":1780842316000}'),n={name:"research/reports/archive/2026-06-03-subagent-agent-team-deep-research.md"};function d(s,t,i,l,g,h){return a(),r("div",null,[...t[0]||(t[0]=[o(`<h1 id="sub-agent-與-agent-team-多代理協作-—-深度研究報告" tabindex="-1">Sub-Agent 與 Agent Team（多代理協作）— 深度研究報告 <a class="header-anchor" href="#sub-agent-與-agent-team-多代理協作-—-深度研究報告" aria-label="Permalink to &quot;Sub-Agent 與 Agent Team（多代理協作）— 深度研究報告&quot;">​</a></h1><blockquote><p><strong>日期</strong>：2026-06-03 ｜ <strong>語言</strong>：繁體中文（技術術語保留英文） <strong>類型</strong>：multi-source deep-research（官方最佳實踐 / GitHub 開源 / 社群討論 / 學術論文 四源） <strong>編排</strong>：<code>research-hub:deep</code>（語料合成）→ 並行 researcher fan-out（四源）→ <code>autoresearch:reason</code>（對抗論證）→ <code>overnight-research</code>（verify + commit 閘門） <strong>定位</strong>：本報告與既有 <code>2026-05-17-claude-code-subagent-delegation-gotchas.md</code>、<code>2026-05-31-consolidated-agent-engineering-research.md</code> 互補——<strong>sub-agent 段引用既有研究不重推，淨新研究力投入 agent-team（多代理團隊協作）維度</strong>。 <strong>引用原則</strong>：所有數據可回溯到具體論文檔名或 URL；二手轉述數字標注來源信度。配套行動計劃見 <code>2026-06-03-subagent-agent-team-execution-plan.md</code>。</p></blockquote><hr><h2 id="執行摘要" tabindex="-1">執行摘要 <a class="header-anchor" href="#執行摘要" aria-label="Permalink to &quot;執行摘要&quot;">​</a></h2><p>2025–2026 年多代理（multi-agent）領域的核心結論已從「要不要用 multi-agent」收斂為「<strong>這個任務形狀適不適合 multi-agent</strong>」。四源證據高度一致地指向同一組設計律：</p><ol><li><strong>Sub-agent 是資訊蒐集者，agent-team 是 context 隔離器</strong>——兩者皆非「平行實作工人」。錯置委派（按任務類型而非 context 邊界分工）會製造 coordination overhead 抵消平行收益。</li><li><strong>成本是硬約束</strong>：多代理系統耗 token 是單次對話的 <strong>15×</strong>（Anthropic 官方），token 使用量解釋了 <strong>80% 的評估變異數</strong>。價值夠高的任務才值得付這個代價。</li><li><strong>拓撲收斂到 Hub-and-Spoke</strong>：2026 生產環境中存活的只有 orchestrator-worker（hierarchical），<strong>open mesh（peer-to-peer 自由協商）幾乎全被淘汰</strong>。</li><li><strong>失敗是結構性的，不是 prompt bug</strong>：MAST 跨 7 框架歸納 14 種失敗模式（κ=0.88），最大兩個瓶頸是 <strong>specification 品質</strong> 與 <strong>task verification</strong>——後者直接對映本 workspace 的 R4（完成條件必須可機械驗證）。</li><li><strong>Debate/consensus 是免訓練的推理增強</strong>，但有 echo-chamber 風險：多代理辯論在 GSM8K +8pp、MMLU +7.2pp，代價是 ~2.5–5× token。</li></ol><p>本 workspace 現行的 <code>subagent-strategy.md</code>（fan-out 上限 4、通訊限 parent↔child、child 不 self-retry、child 輸出只含結果）<strong>與上述四源最佳實踐高度吻合</strong>，甚至比多數官方文件更保守。本報告的價值在於：用外部證據為現行規則背書、補上 agent-team（多代理 debate/consensus/role-based）這個 workspace 尚未系統化的維度，並產出可執行的採用計劃。</p><hr><h2 id="_1-背景-sub-agent-vs-agent-team-的概念分野" tabindex="-1">1. 背景：Sub-Agent vs Agent Team 的概念分野 <a class="header-anchor" href="#_1-背景-sub-agent-vs-agent-team-的概念分野" aria-label="Permalink to &quot;1. 背景：Sub-Agent vs Agent Team 的概念分野&quot;">​</a></h2><p>兩個詞常被混用，但設計意圖不同：</p><table tabindex="0"><thead><tr><th>維度</th><th>Sub-Agent（子代理）</th><th>Agent Team（代理團隊）</th></tr></thead><tbody><tr><td>主隱喻</td><td>「資訊蒐集助手」</td><td>「協作組織 / 公司」</td></tr><tr><td>拓撲</td><td>Orchestrator → workers（單層 fan-out）</td><td>可多層、可 peer、可動態組成</td></tr><tr><td>通訊</td><td>限 parent↔child，child 間不直接溝通</td><td>視框架：handoff / group chat / blackboard</td></tr><tr><td>主用途</td><td>context isolation + 平行蒐集</td><td>角色專業化 + 多輪協作 + 共識</td></tr><tr><td>代表</td><td>Claude Code Agent tool、Claude Agent SDK subagent</td><td>CrewAI、AutoGen GroupChat、MetaGPT、ChatDev</td></tr><tr><td>風險</td><td>過度委派、telephone game 資訊衰減</td><td>coordination overhead、groupthink、成本爆炸</td></tr></tbody></table><p><strong>關鍵洞察</strong>：sub-agent 是 agent-team 的退化特例（單層、單向、無 peer 通訊）。本 workspace 目前只實作到 sub-agent 層（hierarchical fan-out 上限 4），尚未涉足 agent-team 的 debate/consensus/動態組成——這正是淨新研究空間。</p><hr><h2 id="_2-官方最佳實踐-anthropic-openai-google-microsoft" tabindex="-1">2. 官方最佳實踐（Anthropic / OpenAI / Google / Microsoft） <a class="header-anchor" href="#_2-官方最佳實踐-anthropic-openai-google-microsoft" aria-label="Permalink to &quot;2. 官方最佳實踐（Anthropic / OpenAI / Google / Microsoft）&quot;">​</a></h2><h3 id="_2-1-anthropic-—-多代理研究系統-標竿來源" tabindex="-1">2.1 Anthropic — 多代理研究系統（標竿來源） <a class="header-anchor" href="#_2-1-anthropic-—-多代理研究系統-標竿來源" aria-label="Permalink to &quot;2.1 Anthropic — 多代理研究系統（標竿來源）&quot;">​</a></h3><p><strong>來源</strong>：<a href="https://www.anthropic.com/engineering/multi-agent-research-system" target="_blank" rel="noreferrer">How we built our multi-agent research system</a></p><p><strong>架構</strong>：Orchestrator-Worker。Lead Researcher（Opus 4）規劃與合成，平行 subagents（Sonnet 4）各自獨立 context window 探索。</p><p><strong>官方量化數據（一級可信）</strong>：</p><table tabindex="0"><thead><tr><th>指標</th><th>數值</th></tr></thead><tbody><tr><td>多代理 token 用量</td><td>~15× chat interactions</td></tr><tr><td>一般 agent token 用量</td><td>~4× chat interactions</td></tr><tr><td>Token 解釋評估變異數</td><td><strong>80%</strong></td></tr><tr><td>Opus orchestrator + Sonnet workers vs 單 Opus</td><td><strong>+90.2%</strong>（breadth-first research）</td></tr><tr><td>改善工具描述對任務完成時間</td><td><strong>−40%</strong></td></tr></tbody></table><p><strong>官方委派量表</strong>（embed 進 orchestrator 的明確規則）：</p><ul><li>1 agent → 簡單事實查詢</li><li>2–4 agents → 直接比較</li><li>10+ agents → 複雜研究</li></ul><blockquote><p><strong>與本 workspace 衝突點（R7 浮現）</strong>：Anthropic 內部對複雜研究用 <strong>10+</strong> subagents，而 workspace <code>subagent-strategy.md</code> 設 fan-out 上限 <strong>4</strong>。這不是矛盾——workspace 上限是「主對話手動委派」的保守邊界（防 context 污染主線程），而 dynamic workflow 內由 runtime 控管 ≤16 並行 / ≤1000 總量，與 Anthropic 的 10+ 一致。兩者適用範圍不同。</p></blockquote><p><strong>八條官方設計原則</strong>：</p><ol><li>Think like your agents（用真實 prompt 跑模擬，逐步觀察）</li><li>教 orchestrator 如何委派（embed 明確量表）</li><li>工具描述即關鍵路徑（40% 數據佐證）</li><li>Wide-then-narrow 搜尋（先廣再縮）</li><li>Context &gt; 200k 時截斷，orchestrator 先把計畫存 Memory</li><li>Subagent 輸出寫 filesystem，避免 telephone game</li><li>End-state evaluation（只評終態，不逐步審查）</li><li>Rainbow deployments（流量漸移，不中斷跑中 agent）</li></ol><blockquote><p>原文：<em>&quot;Token usage by itself explains 80% of the variance in our evaluations. Multi-agent systems require tasks where the value of the task is high enough to pay for the increased performance.&quot;</em></p></blockquote><h3 id="_2-2-anthropic-—-何時用多代理-三觸發條件" tabindex="-1">2.2 Anthropic — 何時用多代理（三觸發條件） <a class="header-anchor" href="#_2-2-anthropic-—-何時用多代理-三觸發條件" aria-label="Permalink to &quot;2.2 Anthropic — 何時用多代理（三觸發條件）&quot;">​</a></h3><p><strong>來源</strong>：<a href="https://claude.com/blog/building-multi-agent-systems-when-and-how-to-use-them" target="_blank" rel="noreferrer">When to use multi-agent systems</a></p><p>三個官方觸發條件：</p><ol><li><strong>Context Pollution</strong>：子任務 A 的資訊會污染子任務 B</li><li><strong>Parallelization</strong>：子任務可獨立平行</li><li><strong>Specialization</strong>：不同任務需不同工具集或 system prompt 焦點</li></ol><p>核心警告（與 Cognition 立場呼應）：</p><blockquote><p><em>&quot;Teams frequently make this choice incorrectly, leading to coordination overhead that negates the benefits.&quot;</em></p></blockquote><p><strong>設計鐵律</strong>：按 <strong>context 邊界</strong>分工，不按<strong>任務類型</strong>分工。按類型分工 → 每次 handoff 損失 context。</p><h3 id="_2-3-claude-agent-sdk" tabindex="-1">2.3 Claude Agent SDK <a class="header-anchor" href="#_2-3-claude-agent-sdk" aria-label="Permalink to &quot;2.3 Claude Agent SDK&quot;">​</a></h3><p><strong>來源</strong>：<a href="https://claude.com/blog/building-agents-with-the-claude-agent-sdk" target="_blank" rel="noreferrer">Building agents with the Claude Agent SDK</a></p><ul><li>核心隱喻：「Give your agents a computer」</li><li>Agent 迴圈：gather context → take action → verify work → repeat</li><li>Subagent 兩大官方用途：<strong>Parallelization</strong> + <strong>Context isolation</strong></li><li>驗證三法：rules-based feedback / visual feedback / LLM-as-judge</li><li><strong>官方支持 subagent 寫程式碼</strong>（bash、code generation 列為核心能力）</li></ul><h3 id="_2-4-openai-—-agents-sdk-swarm" tabindex="-1">2.4 OpenAI — Agents SDK / Swarm <a class="header-anchor" href="#_2-4-openai-—-agents-sdk-swarm" aria-label="Permalink to &quot;2.4 OpenAI — Agents SDK / Swarm&quot;">​</a></h3><p><strong>來源</strong>：<a href="https://developers.openai.com/cookbook/examples/orchestrating_agents" target="_blank" rel="noreferrer">Orchestrating Agents: Routines and Handoffs</a></p><ul><li>三原語：Agents（LLM+指令+工具）/ Handoffs（peer-to-peer 委派，保留完整 history）/ Guardrails</li><li>兩種拓撲並列：<strong>Handoffs（peer-to-peer）</strong> 與 <strong>Manager-style（hierarchical）</strong></li><li>何時拆 agent：單一 routine 任務太多開始不穩定時</li><li>Fan-out 上限：文件未規定</li></ul><h3 id="_2-5-google-adk-—-八大多代理模式" tabindex="-1">2.5 Google ADK — 八大多代理模式 <a class="header-anchor" href="#_2-5-google-adk-—-八大多代理模式" aria-label="Permalink to &quot;2.5 Google ADK — 八大多代理模式&quot;">​</a></h3><p><strong>來源</strong>：<a href="https://developers.googleblog.com/developers-guide-to-multi-agent-patterns-in-adk/" target="_blank" rel="noreferrer">Developer&#39;s guide to multi-agent patterns in ADK</a></p><table tabindex="0"><thead><tr><th>模式</th><th>適用</th></tr></thead><tbody><tr><td>Sequential Pipeline</td><td>線性確定性流水線</td></tr><tr><td>Coordinator/Dispatcher</td><td>複雜路由（推薦起點）</td></tr><tr><td>Parallel Fan-Out/Gather</td><td>速度關鍵、獨立子任務</td></tr><tr><td>Hierarchical Decomposition</td><td>任務超單 agent context</td></tr><tr><td>Generator and Critic</td><td>需 pass/fail 驗證</td></tr><tr><td>Iterative Refinement</td><td>定性打磨到品質門檻</td></tr><tr><td>Human-in-the-Loop</td><td>高風險動作</td></tr><tr><td>Composite</td><td>真實場景組合</td></tr></tbody></table><p>核心設計原則：<code>session.state</code> 是共享白板；sub-agent 的 <code>description</code> 欄位 = LLM 的 API 文件；<strong>「Start simple: Do not build a nested loop system on day one.」</strong></p><h3 id="_2-6-microsoft-autogen-agent-framework" tabindex="-1">2.6 Microsoft AutoGen / Agent Framework <a class="header-anchor" href="#_2-6-microsoft-autogen-agent-framework" aria-label="Permalink to &quot;2.6 Microsoft AutoGen / Agent Framework&quot;">​</a></h3><p><strong>來源</strong>：<a href="https://microsoft.github.io/autogen/stable//user-guide/core-user-guide/core-concepts/agent-and-multi-agent-application.html" target="_blank" rel="noreferrer">AutoGen Multi-Agent Applications</a></p><ul><li>特色模式：<strong>Mixture of Agents</strong>（多層 worker，類前饋網路）、Group Chat（peer + moderator）、Multi-Agent Debate、Reflection</li><li>v0.4+ async event-driven 架構</li><li><strong>現況</strong>：AutoGen 進入 maintenance mode，Microsoft 推薦新專案用 Microsoft Agent Framework（MAF）</li></ul><h3 id="_2-7-官方共識-vs-分歧" tabindex="-1">2.7 官方共識 vs 分歧 <a class="header-anchor" href="#_2-7-官方共識-vs-分歧" aria-label="Permalink to &quot;2.7 官方共識 vs 分歧&quot;">​</a></h3><p><strong>共識</strong>：</p><ul><li>觸發條件：context 超限 / 可平行 / 需專業化</li><li>預設起點：Orchestrator-Worker（supervisor）</li><li>工具描述品質決定可靠性</li><li>Subagent 應有獨立 context、只回傳相關資訊</li><li>評估用 LLM-as-judge + end-state</li></ul><p><strong>分歧</strong>：</p><table tabindex="0"><thead><tr><th>議題</th><th>Anthropic</th><th>OpenAI</th><th>Google ADK</th><th>AutoGen/MAF</th></tr></thead><tbody><tr><td>用多代理門檻</td><td>高（明示 15× 成本）</td><td>寬鬆</td><td>漸進「start simple」</td><td>企業分散式思維</td></tr><tr><td>Fan-out 上限</td><td>10+（複雜研究）無硬上限</td><td>未規定</td><td>未規定</td><td>未規定</td></tr><tr><td>協作拓撲</td><td>僅推 hierarchical</td><td>handoff + manager 並列</td><td>8 模式，dispatcher 起點</td><td>group chat 為特色</td></tr><tr><td>Subagent 寫碼</td><td>支持</td><td>支持（sandbox）</td><td>支持（custom agent）</td><td>支持</td></tr></tbody></table><hr><h2 id="_3-學術論文證據-全文收錄於-research-papers" tabindex="-1">3. 學術論文證據（全文收錄於 research/papers/） <a class="header-anchor" href="#_3-學術論文證據-全文收錄於-research-papers" aria-label="Permalink to &quot;3. 學術論文證據（全文收錄於 research/papers/）&quot;">​</a></h2><p>本次新下載 6 篇核心論文（PDF + 摘要 md 全文落地），補足 agent-team 的學術骨架：</p><h3 id="_3-1-metagpt-2308-00352-—-sop-即協調協定" tabindex="-1">3.1 MetaGPT（2308.00352）— SOP 即協調協定 <a class="header-anchor" href="#_3-1-metagpt-2308-00352-—-sop-即協調協定" aria-label="Permalink to &quot;3.1 MetaGPT（2308.00352）— SOP 即協調協定&quot;">​</a></h3><p>把人類軟體工程 SOP 直接編碼為 agent prompt sequence，強制<strong>結構化輸出（文件/圖表）而非自由對話</strong>。HumanEval Pass@1 <strong>85.9%</strong>，token 效率比 ChatDev 省 <strong>50%</strong>。</p><blockquote><p><strong>啟示</strong>：限制溝通格式 = 降幻覺 + 提效率。對映 workspace「child 輸出只含結果，JSON→純 JSON」規則。</p></blockquote><h3 id="_3-2-chatdev-2307-07924-—-雙代理對話即驗收" tabindex="-1">3.2 ChatDev（2307.07924）— 雙代理對話即驗收 <a class="header-anchor" href="#_3-2-chatdev-2307-07924-—-雙代理對話即驗收" aria-label="Permalink to &quot;3.2 ChatDev（2307.07924）— 雙代理對話即驗收&quot;">​</a></h3><p>Staged Chat Chain + Communicative Dehallucination：waterfall pipeline 每階段只需一對 agent 對話，角色差異使幻覺被對方追問發現。</p><blockquote><p><strong>啟示</strong>：雙 agent role 差異本身是 verification 信號——一個寫、一個質疑。</p></blockquote><h3 id="_3-3-agentverse-2308-10848-—-動態團隊組成" tabindex="-1">3.3 AgentVerse（2308.10848）— 動態團隊組成 <a class="header-anchor" href="#_3-3-agentverse-2308-10848-—-動態團隊組成" aria-label="Permalink to &quot;3.3 AgentVerse（2308.10848）— 動態團隊組成&quot;">​</a></h3><p>recruit → execute → evaluate → evolve 四階段讓 team 組成隨任務調整。<strong>存在最優 team size</strong>，過多 agent 引入 coordination overhead；groupthink / free-riding 需 orchestrator 主動干預。</p><blockquote><p><strong>啟示</strong>：team size 非越大越好；動態組成優於靜態固定角色。</p></blockquote><h3 id="_3-4-autogen-2308-08155-—-通用對話介面" tabindex="-1">3.4 AutoGen（2308.08155）— 通用對話介面 <a class="header-anchor" href="#_3-4-autogen-2308-08155-—-通用對話介面" aria-label="Permalink to &quot;3.4 AutoGen（2308.08155）— 通用對話介面&quot;">​</a></h3><p>ConversableAgent 支援 LLM/工具/人類任意組合。Three-level 拓撲：Two-Agent / GroupChat / Nested Chat（後者天然支援 hierarchical orchestration，orchestrator 本身可以是 agent）。</p><h3 id="_3-5-multiagent-debate-2305-14325-—-免訓練推理增強" tabindex="-1">3.5 Multiagent Debate（2305.14325）— 免訓練推理增強 <a class="header-anchor" href="#_3-5-multiagent-debate-2305-14325-—-免訓練推理增強" aria-label="Permalink to &quot;3.5 Multiagent Debate（2305.14325）— 免訓練推理增強&quot;">​</a></h3><p>無需訓練的免費增強：arithmetic <strong>+14.8pp</strong>、GSM8K <strong>+8pp</strong>、MMLU <strong>+7.2pp</strong>，黑盒模型同一 prompt 即可部署。</p><blockquote><p><strong>警示</strong>：多 agent 形成錯誤共識（echo chamber）時辯論會固化錯誤，需 diversity preservation。</p></blockquote><h3 id="_3-6-mast-2503-13657-—-為何多代理會失敗" tabindex="-1">3.6 MAST（2503.13657）— 為何多代理會失敗 <a class="header-anchor" href="#_3-6-mast-2503-13657-—-為何多代理會失敗" aria-label="Permalink to &quot;3.6 MAST（2503.13657）— 為何多代理會失敗&quot;">​</a></h3><p>首個實驗性失敗分類：<strong>14 種失敗模式</strong>、κ=0.88，跨 7 框架一致顯示 <strong>specification 品質</strong> 與 <strong>task verification</strong> 是最大瓶頸。Task Verification 失敗（agent 幻覺自報完成）直接對映 workspace R4。</p><blockquote><p><strong>啟示</strong>：失敗是結構性的，不是 prompt bug。可機械驗證的完成條件是防線。</p></blockquote><h3 id="本地既有相關論文-不重抓-交叉引用" tabindex="-1">本地既有相關論文（不重抓，交叉引用） <a class="header-anchor" href="#本地既有相關論文-不重抓-交叉引用" aria-label="Permalink to &quot;本地既有相關論文（不重抓，交叉引用）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>論文</th><th>主題</th></tr></thead><tbody><tr><td>multiagentbench (2503.01935)</td><td>協作/競爭基準（KPI + 里程碑）</td></tr><tr><td>multi-agent-llm-frameworks-benchmark (2602.03128)</td><td>框架架構選擇導致延遲/準確度數量級差距</td></tr><tr><td>multi-agent-memory-computer-architecture (2603.10062)</td><td>計算機架構視角的多代理記憶</td></tr><tr><td>coordination-architectural-layer (2605.03310)</td><td>協調作為獨立架構層</td></tr><tr><td>calbench (2605.09823)</td><td>協調—隱私權衡基準</td></tr><tr><td>generative-agents (2304.03442)</td><td>25 agent 社交模擬</td></tr></tbody></table><hr><h2 id="_4-github-開源生態比較" tabindex="-1">4. GitHub 開源生態比較 <a class="header-anchor" href="#_4-github-開源生態比較" aria-label="Permalink to &quot;4. GitHub 開源生態比較&quot;">​</a></h2><h3 id="_4-1-通用多代理框架" tabindex="-1">4.1 通用多代理框架 <a class="header-anchor" href="#_4-1-通用多代理框架" aria-label="Permalink to &quot;4.1 通用多代理框架&quot;">​</a></h3><table tabindex="0"><thead><tr><th>框架</th><th>⭐</th><th>Team 抽象</th><th>設計取捨</th></tr></thead><tbody><tr><td>LangGraph</td><td>~126k</td><td>有向圖 + 型別化 State + checkpointing</td><td>生產可控性最高；簡單流程「圖抽象過重」</td></tr><tr><td>MetaGPT</td><td>~68k</td><td>軟體公司（PM/Arch/Eng/QA），文件中介</td><td>長任務分工強；token 重複率 72%</td></tr><tr><td>AutoGen</td><td>~54k</td><td>GroupChat + selector</td><td>debate 適合高品質合成；history 累積成本爆炸；maintenance mode</td></tr><tr><td>CrewAI</td><td>~45k</td><td>Role-playing Crew（seq/hierarchical/consensual）</td><td>開發最快；無 checkpointing；簡單任務 token 3×</td></tr><tr><td>ChatDev</td><td>~33k</td><td>虛擬軟體公司（對話式）</td><td>研究/教育強；生產可靠性弱</td></tr><tr><td>OpenAI Swarm</td><td>~21.5k</td><td>Handoff-based</td><td>輕量教育；官方標 non-production</td></tr><tr><td>CAMEL</td><td>~15k</td><td>Role-playing + task dialogue</td><td>學術 scaling study；token 重複率 86%</td></tr><tr><td>Agency Swarm</td><td>~4.4k</td><td>建於 OpenAI SDK 之上</td><td>企業客製化；小社群</td></tr></tbody></table><h3 id="_4-2-claude-code-sub-agent-生態" tabindex="-1">4.2 Claude Code Sub-Agent 生態 <a class="header-anchor" href="#_4-2-claude-code-sub-agent-生態" aria-label="Permalink to &quot;4.2 Claude Code Sub-Agent 生態&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Repo</th><th>⭐</th><th>特性</th></tr></thead><tbody><tr><td>wshobson/agents</td><td>~36k</td><td>84 plugins / 192 agents，單一 MD source 生成 5 個 harness artifact；三層模型策略</td></tr><tr><td>VoltAgent/awesome-claude-code-subagents</td><td>~21k</td><td>154 agents / 10 類；YAML frontmatter role/tools/model routing；least-privilege（reviewer=read-only）</td></tr><tr><td>0xfurai/claude-code-subagents</td><td>~917</td><td>100+ production-ready，context-based 自動委派 + model routing</td></tr></tbody></table><blockquote><p><strong>可借鏡</strong>：VoltAgent 的 least-privilege tool access（reviewer 只給 read-only）與 wshobson 的三層模型策略（Opus 架構 / Sonnet 開發 / Haiku 操作），與本 workspace 的 pilot 模式（haiku/sonnet/opus）及 reviewer 類 agent 工具限制設計同構。</p></blockquote><hr><h2 id="_5-社群討論-共識光譜" tabindex="-1">5. 社群討論：共識光譜 <a class="header-anchor" href="#_5-社群討論-共識光譜" aria-label="Permalink to &quot;5. 社群討論：共識光譜&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>「Multi-Agent 是炒作」←———A———B———C———D———→「Multi-Agent 是必須」</span></span>
<span class="line"><span>                        反方   條件論   正方(條件)  正方(強)</span></span></code></pre></div><p><strong>A — 反方（強）</strong>：Cognition「Don&#39;t Build Multi-Agents」(2025-06)。Devin team 實戰：parallel sub-agents 因 context isolation 衝突（Flappy Bird 例：一 agent 做 Mario 背景、另一做鳥，互不知設計決策）。主張 single-threaded 線性 agent。HN 頂評精煉為「不要建 <em>平行</em> multi-agent」。</p><p><strong>B — 條件論（2026 主流）</strong>：Philipp Schmid 等。sequential/state-dependent → single；parallelizable/exploratory → multi。「framework 選擇次要，eval + observability 才是關鍵」。</p><p><strong>C — 正方（條件）</strong>：Anthropic 研究系統（breadth-first +90.2%）；HN colonCapitalDee：「sub-agent 過濾 web search 結果大幅提升品質，more context is not always better」。</p><p><strong>D — 正方（強）</strong>：特定 structured task（incident response、Meta ranking）有壓倒性優勢，但場景特殊性強。</p><p><strong>生產實測警訊</strong>（信度：中，二手 Medium 數據需獨立驗證）：</p><ul><li>「Fail at Scale」：5 agents 是 inflection point，coordination overhead 使 P99 飆 2.4s；近 50% token 花在 agent 間「重述/調和」；重構為 stateless workers + deterministic planner 後 P99 −73%、cost −80%</li><li>「What Survived 2026」：relay 5 stages 準確度崩至 22.5%（低於 25% 隨機基線）；open mesh 生產淘汰</li></ul><blockquote><p>社群現況共識：<strong>Hub-and-Spoke + stateless workers + artifact contracts</strong> 是被生產驗證的唯一可靠拓撲；context engineering 重要性 ≥ agent 數量。</p></blockquote><hr><h2 id="_6-常見陷阱與反模式-四源交叉驗證" tabindex="-1">6. 常見陷阱與反模式（四源交叉驗證） <a class="header-anchor" href="#_6-常見陷阱與反模式-四源交叉驗證" aria-label="Permalink to &quot;6. 常見陷阱與反模式（四源交叉驗證）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>反模式</th><th>後果</th><th>來源</th><th>防範</th></tr></thead><tbody><tr><td>1</td><td>按任務類型分工（非 context 邊界）</td><td>handoff 損 context、決策盲目</td><td>Anthropic + Cognition</td><td>按 context 邊界拆</td></tr><tr><td>2</td><td>Sub-agent 當平行實作工人</td><td>視野盲目、衝突</td><td>Cognition + 5/17 報告</td><td>sub-agent 只蒐集資訊</td></tr><tr><td>3</td><td>Open mesh peer 自由協商</td><td>relay 準確度崩塌</td><td>Lanham 2026 + MAST</td><td>用 hub-spoke</td></tr><tr><td>4</td><td>Team size 越大越好</td><td>coordination overhead</td><td>AgentVerse</td><td>找最優 size、動態組成</td></tr><tr><td>5</td><td>Agent 幻覺自報完成</td><td>task verification 失敗</td><td>MAST</td><td>機械可驗證完成條件（R4）</td></tr><tr><td>6</td><td>Debate 形成 echo chamber</td><td>固化錯誤</td><td>Multiagent Debate</td><td>diversity preservation</td></tr><tr><td>7</td><td>忽略 token 成本</td><td>15× 爆炸</td><td>Anthropic</td><td>高價值任務才用多代理</td></tr><tr><td>8</td><td>history 全量累積</td><td>每輪成本遞增</td><td>AutoGen GroupChat</td><td>stateless workers + 外部 state</td></tr></tbody></table><hr><h2 id="_7-前沿趨勢與預測" tabindex="-1">7. 前沿趨勢與預測 <a class="header-anchor" href="#_7-前沿趨勢與預測" aria-label="Permalink to &quot;7. 前沿趨勢與預測&quot;">​</a></h2><ol><li><strong>協調成為獨立架構層</strong>（2605.03310）：coordination 不再是 prompt 附帶物，而是可獨立設計/評估的 layer。</li><li><strong>失敗分類學標準化</strong>（MAST 14 模式）：multi-agent debugging 從 ad-hoc 走向 taxonomy-driven。</li><li><strong>動態團隊組成</strong>（AgentVerse）取代靜態角色：recruit-evaluate-evolve 成為高階模式。</li><li><strong>協調—隱私權衡基準化</strong>（calbench 2605.09823）：多代理共享 context 的隱私成本被量化。</li><li><strong>框架收斂</strong>：AutoGen → MAF、Swarm → Agents SDK，輕量教育框架退場，生產框架（LangGraph）與 SDK 化（Agent SDK）並進。</li></ol><hr><h2 id="_8-對本-workspace-的核心發現" tabindex="-1">8. 對本 Workspace 的核心發現 <a class="header-anchor" href="#_8-對本-workspace-的核心發現" aria-label="Permalink to &quot;8. 對本 Workspace 的核心發現&quot;">​</a></h2><ol><li><strong>現行 subagent-strategy.md 獲外部背書</strong>：fan-out 上限 4、通訊限 parent↔child、child 不 self-retry、child 輸出只含結果——四源最佳實踐高度吻合，無需修改核心。</li><li><strong>缺口：agent-team 維度未系統化</strong>——workspace 只到 sub-agent（單層 hierarchical），尚無 debate/consensus/動態組成的可操作模式。<code>gap-vote</code> skill 已是一種 consensus 雛形（2/3 投票），可作為 agent-team 模式的接地點。</li><li><strong>R4（機械可驗證）獲 MAST 學術背書</strong>：task verification 是跨 7 框架最大失敗源，workspace 早已內建防線。</li><li><strong>可借鏡</strong>：least-privilege tool access（VoltAgent）、三層模型路由（wshobson）已部分存在於 pilot 模式，可強化文件化。</li></ol><blockquote><p>完整行動建議見配套計劃書 <code>2026-06-03-subagent-agent-team-execution-plan.md</code>。</p></blockquote><hr><h2 id="附錄-來源評分與索引" tabindex="-1">附錄：來源評分與索引 <a class="header-anchor" href="#附錄-來源評分與索引" aria-label="Permalink to &quot;附錄：來源評分與索引&quot;">​</a></h2><h3 id="官方來源-信度-a" tabindex="-1">官方來源（信度 A） <a class="header-anchor" href="#官方來源-信度-a" aria-label="Permalink to &quot;官方來源（信度 A）&quot;">​</a></h3><ul><li>Anthropic — How we built our multi-agent research system</li><li>Anthropic — When to use multi-agent systems</li><li>Claude Agent SDK docs</li><li>OpenAI Agents SDK / Swarm cookbook</li><li>Google ADK multi-agent patterns</li><li>Microsoft AutoGen docs</li></ul><h3 id="論文-信度-a-全文-pdf-收錄-research-papers" tabindex="-1">論文（信度 A，全文 PDF 收錄 research/papers/） <a class="header-anchor" href="#論文-信度-a-全文-pdf-收錄-research-papers" aria-label="Permalink to &quot;論文（信度 A，全文 PDF 收錄 research/papers/）&quot;">​</a></h3><ul><li>MetaGPT 2308.00352 / ChatDev 2307.07924 / AgentVerse 2308.10848 / AutoGen 2308.08155 / Multiagent Debate 2305.14325 / MAST 2503.13657</li><li>本地既有：multiagentbench 2503.01935、multi-agent-frameworks-benchmark 2602.03128、multi-agent-memory 2603.10062、coordination-layer 2605.03310、calbench 2605.09823、generative-agents 2304.03442</li></ul><h3 id="github-信度-a-一手-repo" tabindex="-1">GitHub（信度 A，一手 repo） <a class="header-anchor" href="#github-信度-a-一手-repo" aria-label="Permalink to &quot;GitHub（信度 A，一手 repo）&quot;">​</a></h3><ul><li>LangGraph / MetaGPT / AutoGen / CrewAI / ChatDev / Swarm / CAMEL / Agency Swarm</li><li>wshobson/agents / VoltAgent/awesome-claude-code-subagents / 0xfurai/claude-code-subagents</li></ul><h3 id="社群-信度-b–c-二手需驗證" tabindex="-1">社群（信度 B–C，二手需驗證） <a class="header-anchor" href="#社群-信度-b–c-二手需驗證" aria-label="Permalink to &quot;社群（信度 B–C，二手需驗證）&quot;">​</a></h3><ul><li>Cognition「Don&#39;t Build Multi-Agents」(信度 A，一手)</li><li>Philipp Schmid Single vs Multi-Agent (信度 A)</li><li>Medium「Fail at Scale」/「What Survived 2026」(信度 C，數字需獨立驗證)</li><li>HN 45096962 討論串</li></ul>`,109)])])}const p=e(n,[["render",d]]);export{u as __pageData,p as default};
